def ref(p):
 p=pathlib.Path(p);p=p if p.is_absolute() else R/p;b=p.read_bytes();assert p.is_file() and not p.is_symlink();return dict(path=str(p.relative_to(R)),sha256='sha256:'+hashlib.sha256(b).hexdigest(),bytes=len(b))
def put(p,v):
 p=O/p;p.parent.mkdir(parents=True,exist_ok=True)
 with p.open('x') as f:json.dump(v,f,ensure_ascii=False,indent=2);f.write('\n')
 return ref(p)
