def verify(x):
 if isinstance(x,list):
  for v in x:verify(v)
 elif isinstance(x,dict):
  if 'path' in x and 'sha256' in x:assert ref(x['path'])==x;bindings[x['path']]=x
  for v in x.values():verify(v)
